) % MOD

matrix_N_plus_1 = matrix_mult(matrix_N, transition_matrix)
result_N_plus_1 = sum(
    sum(initial_state[j] * matrix_N_plus_1[j][i] for j in range(4)) % MOD for i in range(4)
) % MOD

